(6844177, 1028411, 50695, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Bear_Music:</b></div><hr/><i> Even as great as "My Papa''s Waltz"? Fine image, fine poem... </i></td></tr></table> <br/> <br/>ha, that was a candidate, but this first line worked better for the title.</td>', 'Originally posted by Bear_Music: Even as great as "My Papa''s Waltz"? Fine image, fine poem...   ha, that was a candidate, but this first line worked better for the title.', '2012-08-18 23:20:44.000000', NULL, 0);
